contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address a, uint256 n) public payable {
        require(true);

        // Read the owner twice around an unrelated state-changing call to show it is stable.
        address ownerBefore = c.owner();

        // Drive an unrelated public entry that may or may not revert; ownership should not change.
        bool reverted;
        try c.addReward(a) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address ownerAfter = c.owner();

        // The owner is a function of the contract's construction, not of any input or call.
        assert(ownerAfter == ownerBefore);
    }

    receive() external payable {}
}

