contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner) public {
        address ownerBefore = c.owner();
        bool callerIsOwner = (address(this) == ownerBefore);

        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool shouldRevert = (!callerIsOwner) || (newOwner == address(0));
        address ownerAfter = c.owner();

        if (shouldRevert) {
            assert(reverted == true);
        } else {
            assert(reverted == false && ownerAfter == newOwner);
        }
    }

    receive() external payable {}
}

