contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address token) public {
        uint40 beforeLastUpdate = c.rewardData(token).lastUpdateTime;
        uint40 beforePeriodFinish = c.rewardData(token).periodFinish;

        bool reverted;
        try c.addReward(token) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint40 afterLastUpdate = c.rewardData(token).lastUpdateTime;

        if (beforeLastUpdate == 0) {
            assert(
                !reverted &&
                afterLastUpdate != 0
            );
        } else {
            assert(
                reverted &&
                afterLastUpdate == beforeLastUpdate &&
                c.rewardData(token).periodFinish == beforePeriodFinish
            );
        }
    }
}

