contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address rewardToken, address staker, uint256 amount) public {
        require(rewardToken != address(0), "zero reward token");
        require(staker != address(0), "zero staker");

        c.addReward(rewardToken);

        uint256 before = c.rewardPerToken(rewardToken);
        uint256 totalBefore = c.totalSupply();

        uint256 afterCall = c.rewardPerToken(rewardToken);
        uint256 totalAfter = c.totalSupply();

        bool isZeroSupply = (totalBefore == 0 && totalAfter == 0);
        bool nonDecreasing = afterCall >= before;

        assert(isZeroSupply ? (afterCall == before) : nonDecreasing);
    }

    receive() external payable {}
}

