    constructor(C _c) {
        c = _c;
    }

    function run(address rewardToken) public {
        require(rewardToken != address(0), "zero reward token");

        c.addReward(rewardToken);

        uint256 before = c.rewardPerToken(rewardToken);
        uint256 totalSupplyNow = c.totalSupply();

        uint256 afterCall = c.rewardPerToken(rewardToken);

        // totalSupply is zero, so rewardPerToken must return the stored rewardPerTokenStored,
