contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address callerStaker,
        uint256 amount,
        address oldStaking,
        address testedMigrator,
        bool setMigratorFirst
    ) public {
        require(callerStaker != address(0));
        require(amount > 0);
        require(oldStaking != address(0));

        bool setOk;
        if (setMigratorFirst) {
            try c.setMigrator(testedMigrator) { setOk = true; } catch { setOk = false; }
        }

        address effectiveMigrator;
        try c.migrator() returns (address m) { effectiveMigrator = m; } catch { effectiveMigrator = address(0); }

        // If we didn't call setMigrator, the migrator is whatever it was (defaults to address(0));
        // only if setOk is true is effectiveMigrator equal to testedMigrator.
        require(!setMigratorFirst || setOk || effectiveMigrator != testedMigrator);

        uint256 beforeStaker = c.balanceOf(callerStaker);
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeC = address(c).balance;

        bool reverted;
        try c.migrateStake(oldStaking, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterStaker = c.balanceOf(callerStaker);
        uint256 afterTotal = c.totalSupply();
        uint256 afterC = address(c).balance;

        // If the caller was not the migrator (or no migrator was set), the call MUST revert.
        // If it was the migrator, the call may succeed only when it did not revert; and in the
        // success case the contract's total supply and the staker's balance must together grow
        // by exactly the migrated amount.
        assert(
            (effectiveMigrator != address(this) && reverted) ||
            (effectiveMigrator == address(this) && !reverted && afterStaker == beforeStaker + amount && afterTotal == beforeTotal + amount && afterC == beforeC)
        );
    }
}

