        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(c.totalSupply() == beforeTotal + amount);
            assert(c.balanceOf(address(this)) == beforeBal + amount);
        } else {
            assert(c.totalSupply() == beforeTotal);
            assert(c.balanceOf(address(this)) == beforeBal);
        }
    }

    receive() external payable {}
}

