contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address token, uint256 amount) public payable {
        // caller must be the actual msg.sender for c; enforce that this contract
        // calls c as itself, so only the contract address can be the distributor.
        require(caller == address(this), "must call as self");

        bool isRegisteredToken = false;
        {
            // probe: token is registered iff its reward periodFinish getter has been set.
            // addReward sets lastUpdateTime/periodFinish to block.timestamp, which is > 0
            // for any real block; check periodFinish > 0 as observable proxy.
            uint40 pf = c.rewardPeriodFinish(token);
            isRegisteredToken = pf > 0;
        }

        bool isDistributor = (c.rewardDistributor() == address(this));

        // We drive the notifyRewardAmount entry.
        bool reverted;
        uint256 preBal = address(c).balance;
        try c.notifyRewardAmount{value: 0}(token, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: the call reverts exactly when it is not permitted to succeed.
        // Permission conditions are observable: caller is the reward distributor,
        // amount > 0, and the token has been registered via addReward.
        bool shouldRevert = !isDistributor || amount == 0 || !isRegisteredToken;
        assert(reverted == shouldRevert);
    }

    receive() external payable {}
}

