        ) = c.rewardData(rewardToken);

        uint256 totalSupplyBefore = c.totalSupply();
        uint256 rewardPerTokenReturn = c.rewardPerToken(rewardToken);

        uint256 expectedMaxIncrease;
        if (totalSupplyBefore == 0) {
            expectedMaxIncrease = 0;
        } else {
            uint256 finish = periodFinishBefore;
            uint256 effectiveTime = finish < block.timestamp ? finish : block.timestamp;
            uint256 elapsed = effectiveTime > lastUpdateTimeBefore
                ? effectiveTime - lastUpdateTimeBefore
                : 0;
            expectedMaxIncrease = elapsed * uint256(rewardRateBefore) * 1e18 / totalSupplyBefore;
        }

        assert(
            rewardPerTokenReturn == uint256(rewardPerTokenStoredBefore) &&
            rewardPerTokenReturn <= uint256(rewardPerTokenStoredBefore) + expectedMaxIncrease ||
            (totalSupplyBefore != 0 &&
                rewardPerTokenReturn >= uint256(rewardPerTokenStoredBefore) &&
                rewardPerTokenReturn <= uint256(rewardPerTokenStoredBefore) + expectedMaxIncrease)
        );
    }
}

