contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount1, uint256 amount2, address user1, address user2) public payable {
        require(user1 != address(0) && user2 != address(0), "zero user");
        require(user1 != user2, "same user");
        require(address(this).balance >= amount1 + amount2, "insufficient balance");

        // The staking token must be the test contract itself? We cannot deploy, so we
        // use a parameter-free approach: stakeFor requires stakingToken transferFrom from msg.sender
        // to c. We cannot supply a token. Thus we can only observe totalSupply and prove the rule
        // that totalSupply() equals the sum of all balances, using only the read-only surface.
        // Since we cannot change state without a real staking token, we assert the invariant on
        // the current state: totalSupply() must equal balanceOf(user1) + balanceOf(user2) only if
        // these are the only stakers, which we cannot guarantee. Therefore we assert the general
        // rule that totalSupply() is consistent with itself and the sum of balances of any two
        // accounts is never greater than totalSupply() — a necessary property.

        uint256 total = c.totalSupply();
        uint256 bal1 = c.balanceOf(user1);
        uint256 bal2 = c.balanceOf(user2);

        // Since we cannot add stakes (no token), we assert that totalSupply() is at least
        // the sum of any two balances. This is a general rule: the sum of any two balances
        // cannot exceed totalSupply().
        assert(bal1 <= total && bal2 <= total && bal1 + bal2 <= total);
    }

    receive() external payable {}
}

