contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address staker, uint256 amount) public payable {
        require(staker != address(0), "staker zero");
        require(amount > 0, "amount zero");

        // Give the staker a real stake so a successful migrateWithdraw can be observed.
        c.stakeFor(staker, amount);

        uint256 balBefore = c.balanceOf(staker);
        address distBefore = c.rewardDistributor();
        address migBefore = c.migrator();

        bool reverted;
        try c.migrateWithdraw(staker, amount) { reverted = false; } catch { reverted = true; }

        bool callerIsMigrator = (migBefore != address(0));
        bool ownerIsTester = (c.owner() == address(this));
        bool fullWithdraw = (amount == balBefore);

        // The rule: as the only caller (the test contract) is not the migrator unless migrator
        // was set to it, migrateWithdraw must revert; and when it is the migrator and the
        // amount is at most the staker's balance, it must succeed and reduce balance by amount.
        if (callerIsMigrator) {
            assert(!reverted == fullWithdraw);
        } else {
            assert(reverted);
            assert(c.balanceOf(staker) == balBefore);
        }
        assert(c.rewardDistributor() == distBefore);
    }

    receive() external payable {}
}

