contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address _rewardToken, address _account) public {
        require(_rewardToken != address(0), "reward token is zero");
        require(_account != address(0), "account is zero");

        bool added = false;
        if (c.rewardData(_rewardToken).lastUpdateTime() == 0) {
            try c.addReward(_rewardToken) { added = true; } catch { added = false; }
        }
        require(added || c.rewardData(_rewardToken).lastUpdateTime() != 0, "reward token not registered");

        uint256 bal = c.balanceOf(_account);
        uint256 rpt = c.rewardPerToken(_rewardToken);
        uint256 paid = c.userRewardPerTokenPaid(_account, _rewardToken);
        uint256 claim = c.claimableRewards(_account, _rewardToken);

        uint256 got = c.earned(_account, _rewardToken);

        assert(got == bal * (rpt - paid) / 1e18 + claim);
    }
}

