contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address _for, uint256 _amount) public payable {
        uint256 supplyBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(_for);
        bool reverted;
        try c.stakeFor(_for, _amount) { reverted = false; } catch { reverted = true; }

        uint256 supplyAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(_for);

        if (reverted) {
