contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, address token) public {
        // Read the existing distributor (public getter).
        address distributor = c.rewardDistributor();

        // Make this contract the reward distributor so we can drive the happy path.
        c.setRewardDistributor(address(this));

        // Add a fresh reward token owned by msg.sender (may already exist).
        uint40 finishBefore = c.rewardPeriodFinish(token);
        bool addReverted;
        try c.addReward(token) { addReverted = false; } catch { addReverted = true; }

        // The deciding call: notifyRewardAmount from the distributor.
        bool notifyReverted;
        try c.notifyRewardAmount(token, amount) { notifyReverted = false; } catch { notifyReverted = true; }

        // General rule: from a non-distributor caller it must revert; from the
        // distributor it succeeds iff the token is a known reward token and amount > 0.
        bool expectedRevert = !(addReverted || finishBefore != 0) || amount == 0;
        assert(notifyReverted == expectedRevert);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, address token) public {
        // Make this contract the reward distributor so we can drive the happy path.
        c.setRewardDistributor(address(this));

        // Try to add the reward token; it may already exist.
        bool addReverted;
        try c.addReward(token) { addReverted = false; } catch { addReverted = true; }

        // Read the period finish after the (possible) add.
        uint40 finishAfter = c.rewardPeriodFinish(token);

        // The deciding call: notifyRewardAmount from the distributor.
        bool notifyReverted;
        try c.notifyRewardAmount(token, amount) { notifyReverted = false; } catch { notifyReverted = true; }

        // General rule: from the distributor it succeeds iff the token is known (either just added
        // or already present with a nonzero periodFinish) and amount > 0.
        bool known = !addReverted || finishAfter != 0;
        bool expectedRevert = !known || amount == 0;
        assert(notifyReverted == expectedRevert);
    }

    receive() external payable {}
}
